import {phaseFrames,drawFrameBlend} from './fx-animation.mjs';
const isBoss=id=>id?.startsWith('B');
const loadImage=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('妖兽招式素材加载失败'));im.src=src;});
export async function loadMinionFx(assets){if(assets.minionFx)return;assets.minionFxPending??=(async()=>{try{const meta=await fetch('assets/minion-fx/integration-manifest.json').then(r=>{if(!r.ok)throw Error('妖兽招式信息加载失败');return r.json();}),[melee,ranged]=await Promise.all(['melee-v1.png','ranged-v1.png'].map(n=>loadImage('assets/minion-fx/'+n)));const families=Object.fromEntries(meta.families.map(f=>[f.id,{...f,frames:f.frames.map(v=>({rect:v.sourceRect,pivot:v.pivotLocal,groundContactY:v.groundContactPivotLocal?.[1],headPivot:v.projectileHeadPivotLocal}))}]));assets.minionFx={families,mapping:meta.enemyMapping,images:{'melee-v1.png':melee,'ranged-v1.png':ranged}};}catch(e){assets.minionFxPending=null;throw e;}})();await assets.minionFxPending;}
function paint(c,assets,id,phase,x,y,span,options={}){const a=assets.minionFx,f=a?.families[id];if(!f)return false;drawFrameBlend(c,a.images[f.file],options.head?f.frames.map(v=>({...v,pivot:v.headPivot||v.pivot})):f.frames,phase,x,y,span,{reference:f.referenceSpanPixels||256,...options});return true;}
export function minionWindup(c,assets,w,e){if(isBoss(e.enemyKind))return false;const a=e.ai?.attack,s=a?.plan.steps[a.index],id=assets.minionFx?.mapping[e.enemyKind]?.melee;if(!s||a.age>=s.windup||!['melee','dash'].includes(s.type)||!id)return false;c.save();c.translate(e.x+e.face*(e.w+20),e.y-e.h*.45);c.scale(e.face,1);paint(c,assets,id,{a:0,b:1,mix:0},0,0,Math.min(125,(s.reach||70)*1.2),{alpha:.2+.5*a.age/s.windup});c.restore();return true;}
export function minionEffect(c,assets,w,e){if(e.kind!=='enemyVfx'||isBoss(e.enemyKind))return false;const m=assets.minionFx?.mapping[e.enemyKind];if(!m)return false;const id=e.ground&&e.style==='venom'?'poisonPool':e.melee?m.melee:m.impact;if(!id)return false;const f=assets.minionFx.families[id],count=f.frames.length,v=e.melee?1+Math.min(1,e.age/e.duration)*(count-2):Math.min(1,e.age/e.duration)*(count-1),a=Math.min(count-1,Math.floor(v)),phase={a,b:Math.min(count-1,a+1),mix:v-a};c.save();c.translate(e.x,e.y);if(e.melee)c.scale(e.face||1,1);paint(c,assets,id,phase,0,0,Math.max(55,Math.min(220,(e.radius||45)*1.7)),{ground:!!e.ground,alpha:Math.min(1,(e.duration-e.age)*7)});c.restore();return true;}
export function minionProjectile(c,assets,w,s){if(!s.enemySource||isBoss(s.enemyKind))return false;const mapping=assets.minionFx?.mapping[s.enemyKind],id=mapping?.projectile,f=assets.minionFx?.families[id];if(!f)return false;const n=s.age*14,indices=mapping.flightFrames||[2,3],a=indices[Math.floor(n)%indices.length],b=indices[(Math.floor(n)+1)%indices.length];return paint(c,assets,id,{a,b,mix:n%1},s.x,s.y,id==='chainHook'?105:85,{angle:Math.atan2(s.vy,s.vx),head:id==='chainHook'});}
export function minionPoisonPool(c,assets,w,z){if(isBoss(z.enemyKind)||z.style!=='venom'||!assets.minionFx)return false;const age=w.time-z.created,active=age>=z.delay,duration=z.life||3,phase=active?phaseFrames(age-z.delay,duration,{loop:true}):{a:0,b:0,mix:0};return paint(c,assets,'poisonPool',phase,z.x,z.y,z.radius*2,{ground:true,alpha:active?Math.min(1,(z.delay+duration-age)*5):.15+.45*Math.min(1,age/z.delay)});}
